'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const app=$('#app');let session=null,csrf='',lang=localStorage.getItem('ui-lang')||'',content={},offset=0;
const en=()=>lang==='en';const tr=(vi,enText)=>content.translations?.[vi]||(en()?enText:vi);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat(lang==='vi'?'vi-VN':'en-US',{maximumFractionDigits:2}).format(Number(n||0))+' ₫';
const titles={reconciliation:'Đối chiếu Stalwart',placements:'Phân bổ & dung lượng',customers:'Khách hàng',admins:'Quản trị viên',packages:'Gói dịch vụ',domains:'Tên miền',accounts:'Hộp thư',groups:'Nhóm email',aliases:'Bí danh email',subadmins:'Admin phụ',subscriptions:'Đơn hàng & hóa đơn',payments:'Đối soát SePay',servers:'Server Stalwart',jobs:'Hàng đợi đồng bộ',logs:'Nhật ký',trials:'Yêu cầu dùng thử',incidents:'Sự cố hỗ trợ',alerts:'Cảnh báo',health:'Sức khỏe server',changes:'Lịch sử thay đổi',reports:'Báo cáo mail',mailboxes:'Backup hộp thư',recovery:'Recovery server'};
const eng={reconciliation:'Stalwart reconciliation',placements:'Placement & capacity',customers:'Customers',admins:'Administrators',packages:'Service plans',domains:'Domains',accounts:'Mailboxes',groups:'Email groups',aliases:'Email aliases',subadmins:'Delegated admins',subscriptions:'Orders & invoices',payments:'SePay reconciliation',servers:'Stalwart servers',jobs:'Sync queue',logs:'Audit log',trials:'Trial requests',incidents:'Support incidents',alerts:'Alerts',health:'Server health',changes:'Change history',reports:'Mail reports',mailboxes:'Mailbox backups',recovery:'Server recovery'};
const title=k=>en()?(eng[k]||titles[k]||k):(titles[k]||k);
const paths={reconciliation:'/admin/reconciliation',placements:'/admin/placements',dashboard:'/khach-hang',pricing:'/khach-hang/nang-cap',customers:'/bang-quan-tri/khach',admins:'/bang-quan-tri/admin-users',packages:'/bang-quan-tri/goi',domains:'/khach-hang/domain',accounts:'/khach-hang/email',groups:'/khach-hang/nhom',aliases:'/khach-hang/aliases',subadmins:'/khach-hang/admin-phu',subscriptions:'/bang-quan-tri/don-goi',payments:'/admin/payments',servers:'/admin/servers',jobs:'/admin/jobs',logs:'/bang-quan-tri/logs',trials:'/bang-quan-tri/dung-thu',incidents:'/admin/incidents',alerts:'/admin/alerts',health:'/admin/health',changes:'/admin/changes',recovery:'/bang-quan-tri/recovery',mailboxes:'/bang-quan-tri/backup-hop-thu',reports:'/bang-quan-tri/bao-cao-mail',operations:'/bang-quan-tri/van-hanh',backups:'/bang-quan-tri/backup',templates:'/bang-quan-tri/mau-email',languages:'/bang-quan-tri/ngon-ngu',content:'/bang-quan-tri/trang-chu',security:'/tai-khoan',sessions:'/tai-khoan/phien',trial:'/trial',login:'/dang-nhap',register:'/dang-ky',forgot:'/forgot-password',reset:'/reset-password',home:'/'};
const aliases={'/admin':'dashboard','/bang-quan-tri':'dashboard','/customer':'dashboard','/login':'login','/register':'register','/2fa':'mfa','/bang-gia':'home','/packages':'home','/landing':'home','/admin/packages':'packages','/admin/domains':'domains','/bang-quan-tri/domain':'domains','/admin/emails':'accounts','/bang-quan-tri/email':'accounts','/admin/customers':'customers','/admin/subscriptions':'subscriptions','/customer/domains':'domains','/customer/accounts':'accounts','/customer/groups':'groups','/customer/admins':'subadmins','/customer/packages':'pricing','/account/security':'security','/account/sessions':'sessions','/admin/operations':'operations','/admin/advanced':'operations','/bang-quan-tri/nang-cao':'operations','/bang-quan-tri/quan-ly':'operations','/admin/settings':'content','/bang-quan-tri/cau-hinh':'content','/admin/languages':'languages','/bang-quan-tri/ngon-ngu':'languages'};
function current(){if(location.pathname==='/customer/invoice')return'invoice';return Object.keys(paths).find(k=>paths[k]===location.pathname)||aliases[location.pathname]||'home'}
async function api(path,data){const options={headers:{},credentials:'same-origin'};if(data!==undefined){options.method='POST';options.headers={'Content-Type':'application/json','X-CSRF-Token':csrf};options.body=JSON.stringify(data)}const res=await fetch('/api/'+path,options);let result;try{result=await res.json()}catch{throw Error('Phản hồi máy chủ không hợp lệ')}if(!res.ok)throw Error(result.error||result.message||`HTTP ${res.status}`);return result}
function toast(s){const el=$('#toast');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),4500)}
function go(page,query=''){history.pushState({},'',(paths[page]||'/')+query);offset=0;render()}
function badge(v){return `<span class="badge ${escape(v)}">${escape(v)}</span>`}
function header(){const name=content.settings?.landing_brand_name||'Email Business';return `<header><a class="brand" href="/" data-page="home"><span class="brand-mark">✉</span>${escape(name)}</a><nav><button class="mobile-menu secondary" id="mobile">☰</button><button class="secondary" id="language">${escape(content.languages?.find(l=>l.code===lang)?.native_name||lang)}</button>${session?`<a href="/tai-khoan" data-page="security">${escape(session.user.name)}</a><button class="secondary" id="logout">${tr('Thoát','Sign out')}</button>`:`<a href="/dang-nhap" data-page="login">${tr('Đăng nhập','Sign in')}</a><a class="button" href="/dang-ky" data-page="register">${tr('Bắt đầu','Get started')}</a>`}</nav></header>`}
function can(perm){return session?.user.role==='customer'||session?.admin_level==='super'&&session?.user.role==='admin'||session?.permissions?.includes(perm)}
function nav(){const admin=session.user.role==='admin';let menu=[['dashboard',tr('Tổng quan','Overview')],['pricing',tr('Chọn gói','Choose a plan')],['subscriptions',title('subscriptions')],['domains',title('domains')],['accounts',title('accounts')],['groups',title('groups')]];if(session.user.role!=='sub_admin')menu.push(['aliases',title('aliases')],['subadmins',title('subadmins')]);if(admin){menu=[['dashboard',tr('Tổng quan','Overview')],...['customers','packages','subscriptions','domains','accounts','groups','aliases','trials','payments','servers','placements','jobs','operations','reconciliation','reports','health','incidents','alerts','changes','content','languages','templates','backups','mailboxes','recovery','admins','logs'].map(k=>[k,title(k)==='operations'?tr('Vận hành Stalwart','Stalwart operations'):k==='content'?tr('Nội dung & cài đặt','Content & settings'):title(k)])]};return `<aside id="sidebar"><div class="section-label">${admin?'ADMIN CONSOLE':'WORKSPACE'}</div>${menu.map(([k,t])=>`<a class="${current()===k?'active':''}" href="${paths[k]}" data-page="${k}">${escape(t)}</a>`).join('')}<div class="section-label">${tr('Tài khoản','Account')}</div><a href="/tai-khoan" data-page="security">${tr('Bảo mật','Security')}</a><a href="/tai-khoan/phien" data-page="sessions">${tr('Phiên đăng nhập','Sessions')}</a></aside>`}
function shell(html,publicPage=false){app.innerHTML=header()+(session?.impersonator?`<div class="alert" role="status">Đang hỗ trợ khách hàng: ${escape(session.user.email)} <button id="stop-impersonation" class="secondary">Trở về quản trị</button></div>`:'')+(session&&!publicPage?`<div class="shell">${nav()}<main>${html}</main></div>`:html);bindNavigation()}
function bindNavigation(){$('#stop-impersonation')?.addEventListener('click',async()=>{try{await api('auth/impersonation/stop',{});session=await api('auth/me');csrf=session.csrf;go('customers')}catch(e){toast(e.message)}});document.querySelectorAll('[data-page]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();go(a.dataset.page)}));$('#language')?.addEventListener('click',async()=>{const languages=content.languages||[{code:'vi'},{code:'en'}];lang=languages[(languages.findIndex(l=>l.code===lang)+1)%languages.length].code;localStorage.setItem('ui-lang',lang);content=await api('content?lang='+lang);render()});$('#mobile')?.addEventListener('click',()=>$('#sidebar')?.classList.toggle('open'));$('#logout')?.addEventListener('click',async()=>{try{await api('auth/logout',{});session=null;csrf='';go('home')}catch(e){toast(e.message)}})}
function field(name,label,type='text',value='',required=true){return `<label>${escape(label)}<input name="${escape(name)}" type="${type}" value="${escape(value)}" ${required?'required':''} ${type==='password'?'minlength="12" autocomplete="new-password"':''}></label>`}
function formHandler(selector,fn){$(selector)?.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const btn=$('button[type=submit]',form);if(btn)btn.disabled=true;$('.error',form)?.remove();try{await fn(Object.fromEntries(new FormData(form)),form)}catch(err){const el=document.createElement('p');el.className='error';el.textContent=err.message;form.append(el)}finally{if(btn)btn.disabled=false}})}
async function authPage(page){const names={login:tr('Đăng nhập','Sign in'),register:tr('Tạo tài khoản','Create account'),forgot:tr('Quên mật khẩu','Forgot password'),reset:tr('Đặt lại mật khẩu','Reset password'),mfa:tr('Xác thực hai bước','Two-step verification')};let fields='';if(page==='register')fields+=field('name',tr('Họ tên','Full name'));if(['login','register','forgot'].includes(page))fields+=field('email','Email','email');if(['login','register','reset'].includes(page))fields+=field('password',tr('Mật khẩu','Password'),'password');if(page==='mfa')fields+=field('code',tr('Mã xác thực 6 chữ số','6-digit verification code'));shell(`<section class="auth"><div class="card"><p class="eyebrow">EMAIL BUSINESS</p><h1>${names[page]}</h1><form id="authform">${fields}<button type="submit">${names[page]}</button><div class="auth-links"><a href="/dang-nhap" data-page="login">${tr('Đăng nhập','Sign in')}</a><a href="/forgot-password" data-page="forgot">${tr('Quên mật khẩu?','Forgot password?')}</a></div></form></div></section>`,true);formHandler('#authform',async d=>{if(page==='reset')d.token=location.hash.slice(1);const r=await api('auth/'+(page==='mfa'?'mfa':page),d);if(page==='login'){csrf=r.csrf;if(r.mfa){history.pushState({},'','/2fa');return authPage('mfa')}session=await api('auth/me');csrf=session.csrf;go('dashboard')}else if(page==='mfa'){session=await api('auth/me');csrf=session.csrf;go('dashboard')}else{toast(r.message||tr('Đã lưu. Vui lòng đăng nhập.','Saved. Please sign in.'));if(page!=='forgot')go('login')}})}
async function home(){const plans=await api('packages');const sections=Object.fromEntries((content.sections||[]).map(x=>[x.section,x.content]));const visible=k=>sections[k]?.visible!==false&&sections[k]?.enabled!==false;const hero=sections.hero||{};const seo=sections.seo||{};document.documentElement.lang=lang;document.title=seo.title||content.settings?.landing_brand_name||'Email Business';let meta=document.querySelector('meta[name=description]');if(!meta){meta=document.createElement('meta');meta.name='description';document.head.append(meta)}meta.content=seo.description||content.settings?.site_meta_description||'';const sectionHtml=k=>{const x=sections[k];if(!x||!visible(k))return '';return `<section class="card" data-section="${k}"><h2>${escape(x.title||'')}</h2><p>${escape(x.description||'')}</p>${(x.items||[]).map(i=>k==='faq'?`<details><summary>${escape(i.question)}</summary><p>${escape(i.answer)}</p></details>`:`<div class="card"><h3>${escape(i.title||'')}</h3><p>${escape(i.text||'')}</p>${k==='apps'&&String(i.url||'').startsWith('https://')?`<a class="button secondary" href="${escape(i.url)}" rel="noopener">${escape(i.platform||'Tải ứng dụng')}</a>`:''}</div>`).join('')}${k==='cta'?`<a class="button" href="${paths.pricing}" data-page="pricing">${escape(x.button_label||tr('Chọn gói','Select plan'))}</a>`:''}${k==='contact'?`<p>${escape(content.settings?.contact_email||'')} · ${escape(content.settings?.contact_phone||'')}</p><p>${escape(content.settings?.contact_address||'')}</p>`:''}</section>`};shell(`${visible('hero')?`<section class="hero"><span class="eyebrow">${escape(hero.badge||tr('Email doanh nghiệp · Quản lý tập trung','BUSINESS EMAIL · CENTRAL MANAGEMENT'))}</span><h1>${escape(hero.title||tr('Email chuyên nghiệp. Quản lý thật đơn giản.','Professional email. Simply managed.'))}</h1><p>${escape(hero.description||tr('Tên miền riêng, hộp thư cho cả đội ngũ và một nơi để quản lý dịch vụ của bạn.','Your domain, your team’s mailboxes, and one place to manage your service.'))}</p><div class="actions"><a class="button" href="${session?paths.pricing:paths.register}" data-page="${session?'pricing':'register'}">${escape(hero.primary_label||tr('Khám phá gói dịch vụ','Explore service plans'))}</a><a class="button secondary" href="/trial" data-page="trial">${escape(hero.secondary_label||tr('Đăng ký dùng thử','Request a trial'))}</a></div></section>`:''}<section class="public-content">${['about','benefits'].map(sectionHtml).join('')}${visible('pricing')?`<h2>${escape(sections.pricing?.title||tr('Gói dịch vụ','Service plans'))}</h2><p>${escape(sections.pricing?.description||'')}</p><div class="grid">${planCards(plans)}</div><p>${escape(sections.pricing?.note||'')}</p>`:''}${['features','process','apps','faq','cta','contact'].map(sectionHtml).join('')}</section>${visible('footer')?`<footer class="footer">${escape(sections.footer?.description||content.settings?.company_name||'Email Business')} · ${escape(content.settings?.contact_email||'')}</footer>`:''}`,true);bindBuy(plans)}

function planCards(plans){if(!plans.length)return `<div class="card muted">${tr('Chưa có gói dịch vụ được công bố.','No published plans yet.')}</div>`;return plans.map(p=>`<div class="card plan-card"><p class="eyebrow">${escape(content.sections?.find(x=>x.section==='pricing')?.content?.plan_labels?.[p.id]||p.name)}</p><div class="price">${money(p.promo_price>0?p.promo_price:p.price)} <small>/${tr('hộp thư/tháng','mailbox/month')}</small></div><p class="muted">${p.billing_months} ${tr('tháng thanh toán','billing months')}</p><ul><li>${p.min_email_accounts}–${p.max_email_accounts} ${tr('hộp thư','mailboxes')}</li><li>${p.min_domains}–${p.max_domains} ${tr('tên miền','domains')}</li><li>${p.storage_per_account_mb} MB / ${tr('hộp thư','mailbox')}</li><li>${p.duration_days} ${tr('ngày sử dụng','service days')}</li></ul><button data-buy="${p.id}">${tr('Chọn gói','Select plan')}</button></div>`).join('')}
function bindBuy(plans){document.querySelectorAll('[data-buy]').forEach(b=>b.addEventListener('click',()=>{if(!session)return go('register');const p=plans.find(p=>String(p.id)===b.dataset.buy);modal(tr('Đặt gói ','Order ')+p.name,`${field('emails',tr('Số hộp thư','Mailboxes'),'number',p.min_email_accounts)}${field('domains',tr('Số tên miền','Domains'),'number',p.min_domains)}<div id="quote" class="card"></div>`,async d=>{const r=await api('orders',{package_id:p.id,emails:Number(d.emails),domains:Number(d.domains)});closeModal();openInvoice(r.id)},tr('Tạo hóa đơn','Create invoice'));const f=$('#modalform');const update=async()=>{try{const r=await api('quote',{package_id:p.id,emails:Number(f.elements.emails.value),domains:Number(f.elements.domains.value)});$('#quote').textContent=tr('Tổng tiền: ','Total: ')+money(r.total)+` · ${r.emails} ${tr('hộp thư','mailboxes')}, ${r.domains} ${tr('domain','domains')}`;}catch(e){$('#quote').textContent=e.message}};f.addEventListener('input',update);update()}))}
async function dashboard(){const d=await api('dashboard');shell(`<div class="toolbar"><div><p class="eyebrow">WORKSPACE</p><h1>${tr('Tổng quan dịch vụ','Service overview')}</h1></div><a class="button" href="${paths.pricing}" data-page="pricing">${tr('Xem gói dịch vụ','View service plans')}</a></div><div class="grid">${[['domains','Tên miền','Domains'],['accounts','Hộp thư','Mailboxes'],['subscriptions','Gói hoạt động','Active plans'],['pending_invoices','Hóa đơn chờ','Pending invoices']].map(([k,a,b])=>`<div class="card"><span class="muted">${tr(a,b)}</span><div class="stat">${d[k]}</div></div>`).join('')}</div><div class="card"><h2>${tr('Bắt đầu quản lý','Get started')}</h2><p class="muted">${tr('Chọn gói → tạo nhóm → thêm tên miền → tạo hộp thư. Trạng thái đồng bộ thể hiện kết quả xử lý trên Stalwart.','Choose a plan → create a group → add a domain → create a mailbox. Sync status shows the Stalwart processing result.')}</p><div class="actions"><a class="button secondary" data-page="domains" href="${paths.domains}">${title('domains')}</a><a class="button secondary" data-page="accounts" href="${paths.accounts}">${title('accounts')}</a></div></div>${session.user.two_factor_enabled!==1?`<div class="alert">${tr('Tài khoản chưa bật xác thực hai bước.','Two-step verification is not enabled.')} <a data-page="security" href="/tai-khoan">${tr('Thiết lập bảo mật','Configure security')}</a></div>`:''}`)}
function modal(name,fields,submit,button=tr('Lưu','Save')){closeModal();const dialog=document.createElement('dialog');dialog.id='modal';dialog.innerHTML=`<h2>${escape(name)}</h2><form id="modalform">${fields}<div class="actions"><button type="button" class="secondary" id="cancel">${tr('Hủy','Cancel')}</button><button type="submit">${button}</button></div></form>`;document.body.append(dialog);dialog.showModal();$('#cancel').onclick=closeModal;formHandler('#modalform',submit)}
function closeModal(){$('#modal')?.remove()}
const fields={packages:[['name','Tên gói'],['price','Giá/hộp thư/tháng','number',0],['promo_price','Giá khuyến mãi','number',0],['billing_months','Số tháng tính phí','number',12],['duration_days','Số ngày sử dụng','number',365],['min_email_accounts','Số hộp thư tối thiểu','number',1],['max_email_accounts','Số hộp thư tối đa','number',10],['min_domains','Domain tối thiểu','number',1],['max_domains','Domain tối đa','number',3],['extra_domain_price','Phí domain bổ sung','number',0],['storage_per_account_mb','Dung lượng mỗi hộp thư (MB)','number',1024],['max_admin_users','Admin phụ tối đa','number',0],['allow_alias','Cho phép alias (0/1)','number',1],['allow_sub_admin','Cho phép admin phụ (0/1)','number',0],['status','Trạng thái (active/disabled/deleted)','text','active']],customers:[['name','Họ tên'],['email','Email','email'],['password','Mật khẩu ban đầu','password']],admins:[['name','Họ tên'],['email','Email','email'],['password','Mật khẩu ban đầu','password'],['permissions','Quyền (cách nhau bằng dấu phẩy)','text','customers,packages,subscriptions']],domains:[['domain_name','Tên miền']],accounts:[['domain_id','ID domain','number'],['group_id','ID nhóm','number'],['local_part','Tên hộp thư (trước @)'],['display_name','Tên hiển thị'],['password','Mật khẩu hộp thư','password']],groups:[['name','Tên nhóm']],aliases:[['email_account_id','ID hộp thư','number'],['domain_id','ID domain','number'],['local_part','Tên alias (trước @)'],['description','Mô tả']],subadmins:[['name','Họ tên'],['email','Email','email'],['password','Mật khẩu','password'],['permissions','Quyền','text','accounts,domains,groups'],['domain_ids','ID domain được phép (cách bằng dấu phẩy)'],['group_ids','ID nhóm được phép (cách bằng dấu phẩy)']],servers:[['name','Tên server'],['base_url','URL Stalwart','url'],['token','API token hoặc user:password','password'],['dry_run','Dry-run (1) / Live (0)','number',1],['active','Bật (1) / Tắt (0)','number',1],['is_primary','Server chính (0/1)','number',1]],incidents:[['subject','Tiêu đề'],['severity','Mức độ','text','normal'],['root_cause','Nguyên nhân'],['resolution','Cách xử lý']]};
const cols={customers:['id','name','email','status'],admins:['id','name','email','admin_level','status'],packages:['id','name','price','billing_months','max_email_accounts','max_domains','status'],domains:['id','customer_id','domain_name','server_id','status','sync_status','verification_status'],accounts:['id','customer_id','email','group_id','storage_limit_mb','status','sync_status'],groups:['id','customer_id','name','status'],aliases:['id','email_account_id','alias_email','status','sync_status'],subadmins:['id','user_id','permissions','status'],subscriptions:['id','invoice_code','customer_id','price','status','payment_status','end_date'],payments:['id','invoice_code','amount','reference_code','state'],servers:['id','name','base_url','dry_run','active','is_primary'],jobs:['id','job_type','resource_id','status','attempts','last_error'],logs:['id','user_id','action','created_at','context'],trials:['id','name','email','package_id','status'],incidents:['id','customer_id','subject','severity','status'],alerts:['id','server_id','severity','message','status'],health:['id','server_id','mode','status','created_at'],changes:['id','server_id','actor_id','status','created_at']};
function edit(kind,row){let spec=fields[kind];if(!spec)return;if(row&&['customers','admins','accounts','aliases','subadmins','domains','groups'].includes(kind))return;let fs=spec.filter(f=>!row||f[0]!=='password').map(([key,label,type='text',def=''])=>field(key,label,type,row?.[key]??def,!['token','description','root_cause','resolution','display_name'].includes(key))).join('');if(session.user.role==='admin'&&['domains','accounts','groups','aliases','subadmins','incidents'].includes(kind))fs=field('customer_id','ID khách hàng','number')+fs;modal(title(kind),fs,async d=>{for(const [k,,t]of spec){if(t==='number')d[k]=Number(d[k]);if(['permissions','domain_ids','group_ids'].includes(k))d[k]=d[k].split(',').map(x=>x.trim()).filter(Boolean).map(x=>k==='permissions'?x:Number(x))}if(d.customer_id)d.customer_id=Number(d.customer_id);if(!d.token)delete d.token;if(row)d.id=row.id;d.action=row?'update':'create';await api('resources/'+kind,d);closeModal();toast(tr('Đã lưu','Saved'));resourcePage(kind)})}
function rowButtons(kind,r){let b=[];if(kind==='customers'&&r.status==='active'&&session.user.role==='admin'&&can('customers_impersonate'))b.push(['impersonate','Hỗ trợ khách hàng']);if(kind==='trials'&&r.documents?.length)b.push(['documents','Hồ sơ']);if(['packages','servers','incidents'].includes(kind))b.push(['edit','Sửa']);if(kind==='subscriptions'){b.push(['invoice','Hóa đơn']);if(session.user.role==='admin'&&r.status==='pending')b.push(['activate','Xác nhận đã thanh toán'],['cancel','Hủy']);if(session.user.role==='customer'&&['active','expired'].includes(r.status))b.push(['renew','Gia hạn']);}if(kind==='domains'&&r.status!=='deleted')b.push(['dns','Xác minh DNS'],['mail-dns','Kiểm tra DNS email']);if(['domains','accounts','groups','aliases'].includes(kind)&&r.status!=='deleted')b.push(['delete','Xóa']);if(kind==='accounts'&&r.status!=='deleted')b.push(['password','Đổi mật khẩu'],['status',r.status==='active'?'Tạm ngưng':'Bật lại']);if(['customers','admins'].includes(kind)&&r.id!==session.user.id)b.push(['status',r.status==='active'?'Khóa':'Mở khóa']);if(kind==='trials'&&r.status==='pending')b.push(['approve','Duyệt'],['reject','Từ chối']);if(kind==='payments'&&['unmatched','needs_review'].includes(r.state))b.push(['reconcile','Gán hóa đơn']);if(kind==='jobs'&&r.status==='failed')b.push(['retry','Kiểm tra & thử lại']);if(kind==='alerts'&&r.status==='open')b.push(['ack','Xác nhận']);return b.map(([action,t])=>`<button class="secondary" data-action="${action}" data-id="${r.id}">${t}</button>`).join('')}
async function resourcePage(kind,q=''){const r=await api('resources/'+kind+'?offset='+offset+'&q='+encodeURIComponent(q));const columns=cols[kind]||['id','status'];shell(`<div class="toolbar"><h1>${title(kind)}</h1>${fields[kind]?`<button id="create">＋ ${tr('Thêm mới','Add new')}</button>`:''}</div><div class="actions">${kind==='payments'?'<button id="sepay-import" class="secondary">Đọc giao dịch SePay API</button>':''}${kind==='accounts'?'<button id="import-accounts" class="secondary">Import CSV / TXT</button>':''}${['accounts','domains','customers','subscriptions','payments','logs','jobs'].includes(kind)?'<button id="export-csv" class="secondary">Xuất CSV</button>':''}</div><form id="search" class="toolbar"><input name="q" placeholder="${tr('Tìm kiếm…','Search…')}" value="${escape(q)}"><button type="submit" class="secondary">${tr('Tìm kiếm','Search')}</button></form><div class="table-wrap">${r.items.length?`<table><thead><tr>${columns.map(k=>`<th>${escape(k.replaceAll('_',' '))}</th>`).join('')}<th></th></tr></thead><tbody>${r.items.map(x=>`<tr>${columns.map(k=>`<td>${['status','sync_status','payment_status','verification_status','state'].includes(k)?badge(x[k]):escape(typeof x[k]==='object'?JSON.stringify(x[k]):['price','amount'].includes(k)?money(x[k]):x[k])}</td>`).join('')}<td>${rowButtons(kind,x)}</td></tr>`).join('')}</tbody></table>`:`<div class="empty">${tr('Chưa có dữ liệu.','No records yet.')}</div>`}</div><div class="actions">${offset?'<button id="prev" class="secondary">← Trang trước</button>':''}${r.next!==null?'<button id="next" class="secondary">Trang tiếp →</button>':''}</div><p class="note">${tr('Tối đa 50 dòng mỗi trang. Các tác vụ Stalwart được xử lý bởi worker; kiểm tra cột sync status để biết kết quả.','Up to 50 rows per page. Stalwart tasks are processed by the worker; check sync status for the result.')}</p>`);$('#create')?.addEventListener('click',()=>edit(kind));$('#import-accounts')?.addEventListener('click',importAccounts);$('#sepay-import')?.addEventListener('click',()=>modal('Đọc giao dịch SePay',field('from','Từ ngày','date')+field('to','Đến ngày','date')+'<pre id=sepay-result></pre>',async d=>{const r=await api('payments/import',d);$('#sepay-result').textContent=`Đã đọc ${r.read}, ghi nhận ${r.recorded}, trùng ${r.duplicates}, bỏ qua ${r.skipped}. ${r.complete?'Đã đọc hết.':'Chưa đọc hết, chọn khoảng nhỏ hơn.'}`},'Đọc giao dịch'));$('#export-csv')?.addEventListener('click',async()=>{try{await downloadFile('resources/'+kind+'/export?q='+encodeURIComponent(q),kind+'.csv')}catch(e){toast(e.message)}});formHandler('#search',d=>{offset=0;return resourcePage(kind,d.q)});$('#next')?.addEventListener('click',()=>{offset+=50;resourcePage(kind,q)});$('#prev')?.addEventListener('click',()=>{offset=Math.max(0,offset-50);resourcePage(kind,q)});document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>rowAction(kind,r.items.find(x=>String(x.id)===b.dataset.id),b.dataset.action)))}
async function rowAction(kind,r,action){if(action==='mail-dns'){try{const result=await api('domains/'+r.id+'/mail-dns',{});modal('DNS email: '+result.status,result.checks.map(c=>`<div class=card><h3>${escape(c.type)} · ${escape(c.name||'')}</h3>${badge(c.status)}<p>${escape(c.message||'')}</p><p>Mong đợi: ${escape((c.expected||[]).join(' / '))}</p><p>Thực tế: ${escape((c.actual||[]).join(' / '))}</p></div>`).join(''),closeModal,'Đóng')}catch(e){toast(e.message)}return;}if(action==='documents'){modal('Hồ sơ dùng thử',r.documents.map(kind=>`<p><a href="/api/trials/${r.id}/documents/${escape(kind)}">Tải ${kind==='citizen'?'hồ sơ định danh':'giấy phép kinh doanh'}</a></p>`).join(''),closeModal,'Đóng');return;}if(action==='impersonate'){modal('Hỗ trợ khách hàng',`<p>Đăng nhập với quyền của ${escape(r.email)}. Mọi truy cập được ghi nhật ký.</p>`,async()=>{await api('auth/impersonate',{customer_id:r.id});session=await api('auth/me');csrf=session.csrf;closeModal();go('dashboard')},'Bắt đầu hỗ trợ');return;}if(action==='reconcile'){modal('Đối soát thanh toán',field('invoice_code','Mã hóa đơn')+field('note','Lý do đối soát'),async d=>{await api('payments/'+r.id,d);closeModal();resourcePage(kind)});return;}if(action==='dns'){try{const d=await api('domains/'+r.id+'/dns');modal('Xác minh tên miền',`<p>Thêm bản ghi TXT sau vào DNS của bạn:</p><pre>${escape(d.name)}
${escape(d.value)}</pre><h3>Bản ghi dịch vụ email</h3><pre>${escape(d.mail_dns||'Chưa có bản ghi từ Stalwart')}</pre>`,async()=>{const v=await api('domains/'+r.id+'/verify',{});toast(v.verified?'Đã xác minh domain':'Chưa tìm thấy bản ghi TXT; chờ DNS cập nhật rồi thử lại.');closeModal();resourcePage(kind)},'Kiểm tra DNS');}catch(e){toast(e.message)}return;}if(action==='edit')return edit(kind,r);if(action==='invoice')return openInvoice(r.id);if(action==='renew'){try{const order=await api('orders',{package_id:r.package_id,emails:r.selected_email_accounts,domains:r.selected_domains,renewal_for:r.id});return openInvoice(order.id)}catch(e){return toast(e.message)}}let extra='';if(action==='password'||action==='status'&&kind==='accounts'&&r.status!=='active')extra=field('password','Mật khẩu mới','password');const notice=action==='retry'?'Kiểm tra Stalwart trước khi thử lại. Lệnh tạo trước đó có thể đã thành công dù panel chưa nhận được phản hồi.':`Xác nhận thao tác ${action} cho #${r.id}?`;modal('Xác nhận thao tác',`<p>${escape(notice)}</p>${extra}`,async d=>{if(kind==='subscriptions')await api('subscriptions/'+r.id,{action});else if(kind==='trials')await api('trials/'+r.id,{approve:action==='approve'});else{const data={...d,id:r.id,action,customer_id:r.customer_id};if(kind==='aliases')data.email_account_id=r.email_account_id;if(action==='status')data.status=r.status==='active'?'disabled':'active';await api('resources/'+kind,data)}closeModal();toast('Đã ghi nhận');resourcePage(kind)},'Xác nhận')}
function openInvoice(id){history.pushState({},'','/customer/invoice?id='+id);render()}
async function invoice(){const id=new URLSearchParams(location.search).get('id');const {invoice:i,qr_url}=await api('invoices/'+id);shell(`<div class="toolbar"><h1>${tr('Hóa đơn','Invoice')} ${escape(i.invoice_code||'#'+i.id)}</h1>${badge(i.payment_status)}</div><div class="grid"><div class="card"><h2>${escape(i.package_name)}</h2><dl><dt>${tr('Số hộp thư / domain','Mailboxes / domains')}</dt><dd>${i.selected_email_accounts} / ${i.selected_domains}</dd><dt>${tr('Thời gian sử dụng','Service period')}</dt><dd>${escape(i.start_date)} → ${escape(i.end_date)}</dd><dt>${tr('Tổng thanh toán','Total due')}</dt><dd class="price">${money(i.price)}</dd><dt>${tr('Nội dung chuyển khoản','Transfer description')}</dt><dd>${escape(i.bank_transfer_note||i.invoice_code)}</dd></dl><button id="refresh" class="secondary">${tr('Kiểm tra thanh toán','Refresh payment status')}</button></div><div class="card">${qr_url?`<h2>${tr('Thanh toán bằng QR','Pay by QR')}</h2><img class="qr" alt="Payment QR" src="${escape(qr_url)}"><p class="muted">${tr('Giữ nguyên nội dung chuyển khoản. Gói được kích hoạt khi hệ thống nhận đủ tiền.','Keep the transfer description unchanged. Your plan activates after full payment is received.')}</p>`:`<p class="muted">${tr('QR chưa khả dụng hoặc hóa đơn đã được xử lý.','QR unavailable or invoice already processed.')}</p>`}</div></div>`);$('#refresh').onclick=invoice}
async function security(){shell(`<h1>${tr('Bảo mật tài khoản','Account security')}</h1><div class="grid"><div class="card"><h2>Đổi mật khẩu</h2><form id="password-form">${field('password','Mật khẩu hiện tại','password')}${field('new_password','Mật khẩu mới','password')}<button type="submit">Lưu & đăng xuất</button></form></div><div class="card"><h2>Xác thực hai bước</h2><p>Trạng thái: ${session.user.two_factor_enabled===1?'Đã bật ('+escape(session.user.two_factor_method)+')':'Chưa bật'}</p><form id="mfa-setup">${field('password','Mật khẩu hiện tại','password')}<button type="submit">Tạo khóa TOTP</button></form><div id="totp-result"></div><form id="mfa-confirm">${field('password','Mật khẩu hiện tại','password')}${field('code','Mã từ ứng dụng xác thực')}<button type="submit">Bật TOTP</button></form></div></div>`);formHandler('#password-form',async d=>{await api('auth/security',{...d,action:'password'});session=null;go('login')});formHandler('#mfa-setup',async d=>{const r=await api('auth/security',{...d,action:'totp_setup'});$('#totp-result').innerHTML=`<p>Thêm khóa này vào ứng dụng xác thực, sau đó xác nhận mã:</p><pre>${escape(r.secret)}</pre>`});formHandler('#mfa-confirm',async d=>{await api('auth/security',{...d,action:'totp_confirm'});session=await api('auth/me');toast('Đã bật TOTP');security()})}
async function sessions(){const rows=await api('auth/sessions');shell(`<h1>Phiên đăng nhập</h1><div class="stack">${rows.map(r=>`<div class="card"><p>${escape(r.device)}</p><small>${escape(r.created_at)} → ${escape(r.expires_at)}</small><div class="actions"><button class="secondary" data-revoke="${escape(r.id)}">Thu hồi phiên</button></div></div>`).join('')}</div>`);document.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=()=>modal('Thu hồi phiên',field('password','Mật khẩu','password'),async d=>{await api('auth/security',{action:'revoke',session_id:b.dataset.revoke,password:d.password});closeModal();render()}))}
const landingSchema={seo:['title','description'],hero:['badge','title','description','primary_label','secondary_label'],about:['title','description'],benefits:['title','description'],pricing:['title','description','note'],features:['title','description'],process:['title','description'],apps:['title','description'],faq:['title','description'],cta:['title','description','button_label'],contact:['title','description'],footer:['description']};
const landingItems={benefits:['title','text','icon'],features:['title','text','icon'],process:['title','text'],apps:['title','platform','text','url','icon'],faq:['question','answer']};
async function contentPage(code=lang,selected='hero'){const data=await api('content?lang='+encodeURIComponent(code));const saved=data.sections.find(x=>x.section===selected)?.content||{};const items=structuredClone(saved.items||[]);shell(`<h1>Nội dung trang chủ</h1><div class="card"><h2>Thông tin chung</h2><form id="settings">${['landing_brand_name','company_name','contact_email','contact_phone','contact_address','webmail_url','support_url','site_meta_description','trial_require_identity'].map(k=>field(k,k,'text',data.settings?.[k]||'',false)).join('')}<button type="submit">Lưu thông tin chung</button></form></div><div class="card"><h2>Nội dung theo ngôn ngữ</h2><div class="toolbar"><label>Ngôn ngữ<select id="content-language">${data.languages.map(l=>`<option value="${escape(l.code)}" ${l.code===code?'selected':''}>${escape(l.native_name)}</option>`).join('')}</select></label><label>Mục<select id="content-section">${Object.keys(landingSchema).map(k=>`<option ${k===selected?'selected':''}>${k}</option>`).join('')}</select></label></div><form id="section"><label>Hiển thị<select name="visible"><option value="true" ${saved.visible!==false?'selected':''}>Bật</option><option value="false" ${saved.visible===false?'selected':''}>Tắt</option></select></label>${landingSchema[selected].map(k=>k==='description'||k==='note'?`<label>${escape(k)}<textarea name="${k}">${escape(saved[k]||'')}</textarea></label>`:field(k,k,'text',saved[k]||'',false)).join('')}${selected==='pricing'?`<label>Tên hiển thị theo ngôn ngữ (JSON: ID gói → tên)<textarea name="plan_labels">${escape(JSON.stringify(saved.plan_labels||{},null,2))}</textarea></label>`:''}<div id="section-items"></div>${landingItems[selected]?'<button type="button" id="add-item" class="secondary">Thêm mục</button>':''}<button type="submit">Lưu mục ${escape(selected)}</button></form></div>`);const readItems=()=>Array.from(document.querySelectorAll('[data-content-item]')).map(el=>Object.fromEntries(Array.from(el.querySelectorAll('[name]')).map(input=>[input.name,input.value])));const drawItems=()=>{const keys=landingItems[selected]||[];$('#section-items').innerHTML=items.map((row,i)=>`<div class="card" data-content-item="${i}">${keys.map(k=>field(k,k,'text',row[k]||'',false)).join('')}<div class="actions"><button type="button" class="secondary" data-move="${i}" data-delta="-1" ${i===0?'disabled':''}>Lên</button><button type="button" class="secondary" data-move="${i}" data-delta="1" ${i===items.length-1?'disabled':''}>Xuống</button><button type="button" class="danger" data-remove="${i}">Xóa</button></div></div>`).join('');document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{items.splice(0,items.length,...readItems());const i=Number(b.dataset.move),j=i+Number(b.dataset.delta);[items[i],items[j]]=[items[j],items[i]];drawItems()});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{items.splice(0,items.length,...readItems());items.splice(Number(b.dataset.remove),1);drawItems()})};drawItems();$('#add-item')?.addEventListener('click',()=>{items.splice(0,items.length,...readItems());items.push({});drawItems()});$('#content-language').onchange=e=>contentPage(e.target.value,selected);$('#content-section').onchange=e=>contentPage(code,e.target.value);formHandler('#settings',async d=>{await api('content',{kind:'settings',entries:d});content=await api('content?lang='+lang);toast('Đã lưu')});formHandler('#section',async d=>{const value=Object.fromEntries(landingSchema[selected].map(k=>[k,d[k]||'']));value.visible=d.visible==='true';if(landingItems[selected])value.items=readItems();if(selected==='pricing')value.plan_labels=JSON.parse(d.plan_labels);await api('content',{kind:'section',language:code,section:selected,content:value});content=await api('content?lang='+lang);toast('Đã lưu mục '+selected)})}
async function languagesPage(code='',entryOffset=0,q=''){const data=await api('languages?code='+encodeURIComponent(code)+'&offset='+entryOffset+'&q='+encodeURIComponent(q));shell(`<h1>Ngôn ngữ và bản dịch</h1><div class="card"><h2>Quản lý ngôn ngữ</h2>${data.languages.map(l=>`<p>${escape(l.native_name)} (${escape(l.code)}) ${l.code===data.default?'— mặc định':''} <button class="secondary" data-language-edit="${escape(l.code)}">Sửa</button><button class="secondary" data-language-default="${escape(l.code)}">Đặt mặc định</button>${l.code!==data.default?`<button class="danger" data-language-delete="${escape(l.code)}">Xóa</button>`:''}</p>`).join('')}<button id="language-create">Thêm ngôn ngữ</button></div><div class="card"><h2>Bản dịch</h2><form id="language-search" class="toolbar"><select name="code">${data.languages.map(l=>`<option value="${escape(l.code)}" ${l.code===data.code?'selected':''}>${escape(l.native_name)}</option>`).join('')}</select>${field('q','Tìm kiếm','text',q,false)}<button type="submit">Tìm</button></form><form id="language-entries">${data.entries.map((e,i)=>`<label>${escape(e.key)}<textarea name="entry-${i}">${escape(e.value)}</textarea></label>`).join('')}<button type="submit">Lưu trang này</button></form><div class="actions">${entryOffset?'<button id="language-prev" class="secondary">Trang trước</button>':''}${data.next!==null?'<button id="language-next" class="secondary">Trang tiếp</button>':''}</div></div>`);formHandler('#language-search',d=>languagesPage(d.code,0,d.q));formHandler('#language-entries',async d=>{const entries=Object.fromEntries(data.entries.map((e,i)=>[e.key,d['entry-'+i]]));await api('languages',{action:'entries',code:data.code,entries});content=await api('content?lang='+lang);toast('Đã lưu 80 dòng của trang hiện tại')});$('#language-prev')?.addEventListener('click',()=>languagesPage(data.code,Math.max(0,entryOffset-80),q));$('#language-next')?.addEventListener('click',()=>languagesPage(data.code,data.next,q));const edit=l=>modal('Ngôn ngữ',field('code','Mã (ví dụ: vi, en)', 'text',l?.code||'')+field('name','Tên','text',l?.name||'')+field('native_name','Tên bản địa','text',l?.native_name||'')+`<label>Trạng thái<select name="enabled"><option value="true" ${l?.enabled!==0?'selected':''}>Bật</option><option value="false" ${l?.enabled===0?'selected':''}>Tắt</option></select></label>`,async d=>{if(l&&d.code!==l.code)throw Error('Không đổi mã; hãy tạo ngôn ngữ mới');await api('languages',{...d,action:'metadata',enabled:d.enabled==='true'});closeModal();languagesPage(d.code)});$('#language-create').onclick=()=>edit();document.querySelectorAll('[data-language-edit]').forEach(b=>b.onclick=()=>edit(data.languages.find(l=>l.code===b.dataset.languageEdit)));document.querySelectorAll('[data-language-default]').forEach(b=>b.onclick=async()=>{try{await api('languages',{action:'default',code:b.dataset.languageDefault});languagesPage(data.code)}catch(e){toast(e.message)}});document.querySelectorAll('[data-language-delete]').forEach(b=>b.onclick=()=>modal('Xóa ngôn ngữ','<p>Xóa bản dịch và nội dung của ngôn ngữ này?</p>',async()=>{await api('languages',{action:'delete',code:b.dataset.languageDelete});closeModal();languagesPage()},'Xóa'))}

async function backupsPage(){const data=await api('backups');const p=data.policy;shell(`<h1>Backup và phục hồi</h1><div class="card"><h2>Backup PostgreSQL được mã hóa</h2><p>Backup này chứa dữ liệu panel. Dữ liệu hộp thư và cấu hình Stalwart cần backup riêng.</p><button id="backup-create">Tạo backup</button><button id="backup-refresh" class="secondary">Làm mới</button><div class="table-wrap"><table><thead><tr><th>ID</th><th>Thời gian</th><th>Trạng thái</th><th>Dung lượng</th><th>Cloud</th><th></th></tr></thead><tbody>${data.backups.map(b=>`<tr><td>${b.id}</td><td>${escape(b.created_at)}</td><td>${badge(b.status)} ${escape(b.last_error||'')}</td><td>${escape(b.bytes||'')}</td><td>${badge(b.cloud_status)} ${escape(b.retrieval_status||'')}</td><td>${b.cloud_status==='uploaded'&&!b.local_available?`<button class="secondary" data-backup-retrieve="${b.id}">Tải từ cloud</button>`:''}${b.status==='done'&&b.local_available?`<a href="/api/backups/${b.id}/download">Tải backup</a> <button class="secondary" data-restore="${b.id}">Phục hồi tách biệt</button>`:''}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Lịch chạy và lưu trữ</h2><form id="backup-policy"><label>Tự động<select name="enabled"><option value="false" ${!p.enabled?'selected':''}>Tắt</option><option value="true" ${p.enabled?'selected':''}>Bật</option></select></label>${field('interval_hours','Chu kỳ (giờ)','number',p.interval_hours)}${field('keep_local','Số bản giữ tại máy','number',p.keep_local)}${field('keep_cloud','Số bản giữ trên cloud','number',p.keep_cloud)}${field('destination','Đích cloud (remote rclone:folder)','text',p.destination,false)}<p>Cấu hình remote và thông tin truy cập cloud riêng trên server. Chỉ xóa các bản backup do panel tạo theo chính sách này.</p><button type="submit">Lưu chính sách</button></form></div>`);document.querySelectorAll('[data-backup-retrieve]').forEach(b=>b.onclick=async()=>{try{await api('backups/'+b.dataset.backupRetrieve+'/retrieve',{});toast('Đã xếp lịch tải cloud');await backupsPage()}catch(e){toast(e.message)}});$('#backup-refresh').onclick=backupsPage;$('#backup-create').onclick=async()=>{try{await api('backups',{});toast('Đã đưa yêu cầu backup vào hàng đợi');backupsPage()}catch(e){toast(e.message)}};formHandler('#backup-policy',async d=>{await api('backups/policy',{...d,enabled:d.enabled==='true',interval_hours:Number(d.interval_hours),keep_local:Number(d.keep_local),keep_cloud:Number(d.keep_cloud)});toast('Đã lưu chính sách')});document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>modal('Phục hồi vào database trống',`<p>Chuẩn bị database đích trống, tách biệt trước khi phục hồi. Database panel đang chạy được bảo vệ.</p>${field('database','Database đích')}${field('confirm_database','Nhập lại database đích')}${field('password','Mật khẩu quản trị','password')}`,async d=>{await api('backups/'+b.dataset.restore+'/restore',d);closeModal();toast('Đã phục hồi vào '+d.database)},'Xác nhận phục hồi'))}
async function templatesPage(){const data=await api('email-templates');shell(`<h1>Mẫu email và thông báo</h1><p>${data.smtp_configured?'SMTP đã cấu hình':'Cần cấu hình SMTP để gửi email'}</p><p>Hàng đợi: ${escape(JSON.stringify(data.queue))}</p>${data.templates.map(t=>`<div class="card"><h2>${escape(t.name)}</h2><form data-template="${escape(t.template_key)}">${field('name','Tên','text',t.name)}${field('subject','Tiêu đề','text',t.subject)}<label>Nội dung<textarea name="body">${escape(t.body)}</textarea></label><label>Trạng thái<select name="enabled"><option value="true" ${t.enabled===1?'selected':''}>Bật</option><option value="false" ${t.enabled===0?'selected':''}>Tắt</option></select></label><button type="submit">Lưu mẫu</button></form></div>`).join('')}<div class="card"><h2>Thông báo cho khách hàng đang hoạt động</h2><form id="broadcast">${field('subject','Tiêu đề')}<label>Nội dung<textarea name="message" required></textarea></label>${field('password','Mật khẩu quản trị','password')}<button type="submit">Xác nhận đưa vào hàng đợi</button></form></div>`);for(const t of data.templates)formHandler(`[data-template="${t.template_key}"]`,async d=>{await api('email-templates',{...d,template_key:t.template_key,enabled:d.enabled==='true'});toast('Đã lưu mẫu')});let requestId=crypto.randomUUID();formHandler('#broadcast',async(d,form)=>{const r=await api('email-broadcast',{...d,request_id:requestId});requestId=crypto.randomUUID();form.elements.password.value='';toast(`Đã đưa ${r.queued} email vào hàng đợi`)})}
const managementKinds={queue:'Hàng đợi giao thư',tasks:'Tác vụ bảo trì',dns_domains:'DNS & chứng chỉ domain',dns_servers:'Server DNS',dkim_keys:'Khóa DKIM',roles:'Vai trò',tenants:'Tenant',api_keys:'Khóa API',app_passwords:'Mật khẩu ứng dụng',outbound:'Giới hạn gửi',inbound:'Giới hạn nhận',blocked:'IP bị chặn',allowed:'IP được cho phép',certificates:'Chứng chỉ',logs:'Log server',traces:'Theo dõi giao thư',dmarc_reports:'Báo cáo DMARC',tls_reports:'Báo cáo TLS',arf_reports:'Báo cáo lạm dụng',metrics:'Số liệu server'};
const managementActions={queue:['retry','defer','cancel','pause','resume'],tasks:['retry','recalculate_quota','reindex_account','recalculate_imap_uid','reload_tls','reload_settings','reload_lookup','update_spam_rules'],dns_domains:['dns_publish','renew_certificate','dkim_cycle'],roles:['create','update','destroy'],tenants:['create','update','destroy'],api_keys:['create','rotate','destroy'],app_passwords:['create','rotate','destroy'],outbound:['create','update','disable','destroy'],inbound:['create','update','disable','destroy'],blocked:['create','destroy'],allowed:['create','destroy']};
const actionLabels={retry:'Thử lại',defer:'Hoãn một giờ',cancel:'Hủy thư',pause:'Tạm dừng giao thư',resume:'Tiếp tục giao thư',recalculate_quota:'Tính lại dung lượng',reindex_account:'Lập lại chỉ mục',recalculate_imap_uid:'Tính lại IMAP UID',reload_tls:'Nạp lại chứng chỉ TLS',reload_settings:'Nạp lại cài đặt',reload_lookup:'Nạp lại dữ liệu tra cứu',update_spam_rules:'Cập nhật luật chống spam',dns_publish:'Xuất bản DNS',renew_certificate:'Gia hạn chứng chỉ',dkim_cycle:'Luân chuyển DKIM',create:'Tạo mới',update:'Cập nhật',rotate:'Tạo credential thay thế',disable:'Tắt',destroy:'Xóa'};
async function operations(){
 const servers=await api('resources/servers');
 shell(`<h1>${tr('Vận hành Stalwart','Stalwart operations')}</h1><p class="alert">Các thay đổi có bước xem trước và xác nhận dùng một lần. Server dry-run chỉ mô phỏng.</p><div class="card"><form id="manage-list"><label>Server<select name="server_id">${servers.items.filter(s=>s.active===1).map(s=>`<option value="${s.id}">${escape(s.name)}${s.dry_run?' (dry-run)':''}</option>`).join('')}</select></label><label>Nghiệp vụ<select name="kind">${Object.entries(managementKinds).map(([k,label])=>`<option value="${k}">${escape(label)}</option>`).join('')}</select></label><button type="submit">Tải dữ liệu</button></form><p id="manage-mode"></p><div class="table-wrap" id="manage-data"></div><button class="secondary" id="manage-next" hidden>Trang tiếp theo</button></div><div class="card"><form id="manage-change"><label>Thao tác<select name="action"></select></label><div id="manage-fields"></div><button type="submit">Xem trước thay đổi</button></form><div id="manage-review"></div></div><details class="card"><summary>Gắn khách hàng vào tenant</summary><p>Tenant phải tồn tại và các domain hiện có phải thuộc tenant đó.</p><form id="tenant-bind">${field('customer_id','ID khách hàng','number')}${field('tenant_id','ID tenant')}${field('version','Phiên bản liên kết (0 nếu mới)','number',0)}<button>Lưu liên kết</button></form><pre id="tenant-result"></pre></details><details class="card"><summary>Chuyển liên kết sang server khác</summary><p>Hoàn tất sao chép dữ liệu và phục hồi thử trước khi chuyển. Hệ thống kiểm tra domain, tài khoản, quota và bí danh ở server đích.</p><form id="migrate-preview">${field('domain_id','ID domain','number')}${field('target_server_id','ID server đích','number')}<label>Ánh xạ ID đích<textarea name="mappings" required placeholder='{"domain_id":"remote-domain","accounts":{"1":"remote-account"}}'></textarea></label>${['backup','restore','delivery','dns'].map((k,i)=>`<label><input type="checkbox" name="${k}" required> ${['Đã backup','Đã phục hồi thử','Đã thử giao thư','Đã chuẩn bị DNS'][i]}</label>`).join('')}<button>Xem trước chuyển liên kết</button></form><div id="migrate-review"></div></details>`);
 const listForm=$('#manage-list'), changeForm=$('#manage-change');let cursor=0,next=null,loaded=null;
 function fields(){const kind=listForm.elements.kind.value,action=changeForm.elements.action.value;let html='';if(['recalculate_quota','reindex_account','recalculate_imap_uid'].includes(action))html=field('account_id','ID hộp thư trên panel','number');if(['create','update','rotate'].includes(action)){if(['roles','api_keys','app_passwords','outbound'].includes(kind))html+=field('description','Mô tả');if(['roles','tenants','api_keys','app_passwords'].includes(kind))html+=field('permissions','Quyền server (phân cách bằng dấu phẩy)');if(kind==='roles')html+=field('tenant_id','ID tenant (không bắt buộc)','text','',false);if(kind==='tenants'){html+=field('name','Tên tenant');for(const [k,label]of Object.entries({maxAccounts:'Số tài khoản',maxDomains:'Số domain',maxGroups:'Số nhóm',maxRoles:'Số vai trò',maxDiskQuota:'Dung lượng tối đa (byte)'}))html+=field(k,label+'; 0 = không giới hạn','number',0);}if(['api_keys','app_passwords'].includes(kind))html+=field('expires_at','Hết hạn (RFC3339)','text',new Date(Date.now()+30*86400000).toISOString())+field('allowed_ips','IP/CIDR được phép (để trống = tất cả)','text','',false);if(['inbound','outbound'].includes(kind))html+=`<label>Phạm vi<select name="scope">${(kind==='outbound'?['sender','senderDomain','rcptDomain']:['authenticatedAs','senderDomain','rcptDomain']).map(k=>`<option>${k}</option>`).join('')}</select></label>`+field('value','Email hoặc domain')+field('count','Số thư','number',100)+field('minutes','Trong số phút','number',60);if(['blocked','allowed'].includes(kind))html+=field('value','IP/CIDR')+field('expires_at','Hết hạn (RFC3339)','text',new Date(Date.now()+86400000).toISOString())+(kind==='allowed'?field('description','Lý do'): '');}$('#manage-fields').innerHTML=html;changeForm.hidden=!(managementActions[kind]?.length);}
 function category(){changeForm.elements.action.innerHTML=(managementActions[listForm.elements.kind.value]||[]).map(k=>`<option value="${k}">${escape(actionLabels[k])}</option>`).join('');fields();$('#manage-review').textContent='';loaded=null;$('#manage-data').textContent='';cursor=0;next=null;$('#manage-next').hidden=true;}
 listForm.elements.kind.onchange=category;listForm.elements.server_id.onchange=category;changeForm.elements.action.onchange=fields;category();
 async function load(){const server_id=Number(listForm.elements.server_id.value),kind=listForm.elements.kind.value;const r=await api('management/list',{server_id,kind,offset:cursor});loaded={server_id,kind};next=r.next;$('#manage-mode').textContent=`${r.mode==='dry_run'?'Mô phỏng':'Dữ liệu server thật'} · ${r.total??'?'} mục`;$('#manage-data').innerHTML=`<table><thead><tr><th>Chọn</th><th>ID</th><th>Thông tin</th></tr></thead><tbody>${r.items.map(row=>`<tr><td><input type="checkbox" class="manage-selected" value="${escape(row.id)}" aria-label="Chọn ${escape(row.id)}"></td><td>${escape(row.id)}</td><td><details><summary>${escape(row.name||row.description||row.selector||row['@type']||row.id)}</summary><pre>${escape(JSON.stringify(row,null,2))}</pre></details></td></tr>`).join('')||'<tr><td colspan="3">Không có dữ liệu</td></tr>'}</tbody></table>`;$('#manage-next').hidden=next===null;}
 formHandler('#manage-list',async()=>{cursor=0;await load()});$('#manage-next').onclick=async()=>{try{cursor=next;await load()}catch(e){toast(e.message)}};
 formHandler('#manage-change',async d=>{const server_id=Number(listForm.elements.server_id.value),kind=listForm.elements.kind.value;const ids=[...document.querySelectorAll('.manage-selected:checked')].map(c=>c.value);if(ids.length&&(!loaded||loaded.server_id!==server_id||loaded.kind!==kind))throw Error('Tải lại dữ liệu trước khi chọn');const data={...d};for(const k of ['account_id','maxAccounts','maxDomains','maxGroups','maxRoles','maxDiskQuota','count','minutes'])if(k in data)data[k]=Number(data[k]);const r=await api('management/preview',{server_id,kind,action:d.action,ids,fields:data});$('#manage-review').innerHTML=`<h3>Kế hoạch #${r.plan_id}: ${escape(actionLabels[d.action])}</h3><pre>${escape(JSON.stringify({before:r.before,changes:r.calls},null,2))}</pre><p class="alert">${escape(r.warning)}</p><button id="manage-execute" class="danger">Xác nhận thực hiện</button>`;$('#manage-execute').onclick=async e=>{e.target.disabled=true;try{const result=await api('operations/execute/'+r.plan_id,{});$('#manage-review').innerHTML=`<p>${escape(result.status)}</p><pre>${escape(JSON.stringify(result.result,null,2))}</pre>${result.secret_available?'<button id="reveal-secret">Xem credential một lần</button><pre id="credential-secret"></pre>':''}`;if(result.secret_available)$('#reveal-secret').onclick=()=>modal('Xem credential một lần',field('password','Mật khẩu panel','password'),async data=>{const value=await api('management/secrets/'+r.plan_id,{password:data.password});$('#credential-secret').textContent=value.secret;$('#reveal-secret').disabled=true;closeModal();toast('Lưu credential an toàn. Hệ thống không cung cấp lại giá trị này.');},'Xem credential');}catch(err){toast(err.message)}};});
 formHandler('#tenant-bind',async d=>{$('#tenant-result').textContent=JSON.stringify(await api('tenant-bindings',{server_id:Number(listForm.elements.server_id.value),customer_id:Number(d.customer_id),tenant_id:d.tenant_id,version:Number(d.version)}),null,2)});
 formHandler('#migrate-preview',async d=>{const r=await api('migrations/preview',{domain_id:Number(d.domain_id),target_server_id:Number(d.target_server_id),mappings:JSON.parse(d.mappings),checklist:Object.fromEntries(['backup','restore','delivery','dns'].map(k=>[k,$('#migrate-preview').elements[k].checked]))});$('#migrate-review').innerHTML=`<pre>${escape(JSON.stringify(r,null,2))}</pre><form id="migrate-apply">${field('confirmation','Nhập MIGRATE để xác nhận')}<button class="danger">Chuyển liên kết</button></form>`;formHandler('#migrate-apply',async data=>{await api('migrations/'+r.plan_id+'/apply',data);$('#migrate-review').textContent='Đã chuyển liên kết sang server đích';});});
}

async function trial(){const plans=await api('packages');shell(`<h1>Đăng ký dùng thử</h1><div class="card"><p>Thời gian dùng thử 14 ngày, sau khi quản trị viên duyệt.</p><form id="trial">${!session?field('name',tr('Họ tên','Full name'))+field('email','Email','email'):''}<label>Gói<select name="package_id">${plans.map(p=>`<option value="${p.id}">${escape(p.name)}</option>`).join('')}</select></label>${field('phone','Điện thoại')}${field('address','Địa chỉ')}${field('company_name','Tên công ty','text','',false)}${field('citizen_id','Số định danh','text','',false)}<label>Hồ sơ định danh (JPG, PNG, PDF; tối đa 5 MB)<input name="citizen" type="file" accept="image/jpeg,image/png,application/pdf" ${content.settings?.trial_require_identity==='0'?'':'required'}></label><label>Giấy phép kinh doanh (không bắt buộc)<input name="business_license" type="file" accept="image/jpeg,image/png,application/pdf"></label><button type="submit">Gửi yêu cầu</button></form></div>`);formHandler('#trial',async(d,form)=>{const documents={};for(const kind of ['citizen','business_license']){const file=form.elements[kind].files[0];if(file)documents[kind]=await encodeDocument(file)}await api(session?'trials':'trials/public',{name:d.name,email:d.email,package_id:Number(d.package_id),phone:d.phone,address:d.address,company_name:d.company_name,citizen_id:d.citizen_id,documents});toast('Đã nhận yêu cầu dùng thử');go(session?'dashboard':'home')})}
async function encodeDocument(file){if(file.size>5*1024*1024)throw Error('Tệp tối đa 5 MB');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Không đọc được tệp'));reader.onload=()=>resolve({mime:file.type,data:String(reader.result).split(',')[1]});reader.readAsDataURL(file)})}
async function downloadFile(path,name){const response=await fetch('/api/'+path,{credentials:'same-origin'});if(!response.ok){let body;try{body=await response.json()}catch{}throw Error(body?.error||'Không tải được tệp')}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importAccounts(){modal('Import hộp thư',`${session.user.role==='admin'?field('customer_id','ID khách hàng','number'):''}<p>Mỗi dòng: tên, họ, email@domain, mật khẩu (tối thiểu 12 ký tự), ID nhóm. Domain phải được xác minh và đồng bộ. Tối đa 200 dòng.</p><label>Tệp CSV / TXT<input name="file" type="file" accept=".csv,.txt,text/plain,text/csv" required></label><pre id="import-result" aria-live="polite"></pre>`,async(d,form)=>{const file=form.elements.file.files[0];if(file.size>60000)throw Error('Tệp tối đa 60 KB');const result=await api('accounts/import',{text:await file.text(),customer_id:Number(d.customer_id)});$('#import-result').textContent=`Đã tạo ${result.created}, lỗi ${result.failed}.\n`+result.errors.map(e=>`Dòng ${e.row}: ${e.error}`).join('\n');form.elements.file.value='';},'Import')}

async function render(){const page=current();try{if(['login','register','forgot','reset','mfa'].includes(page)){if(session&&['login','register','mfa'].includes(page))return go('dashboard');return await authPage(page)}if(page==='home')return await home();if(!session&&page==='trial')return await trial();if(!session)return go('login');if(page==='dashboard')return await dashboard();if(page==='pricing'){const plans=await api('packages');shell(`<h1>${tr('Chọn gói dịch vụ','Choose a service plan')}</h1><div class="grid">${planCards(plans)}</div><a class="button secondary" href="/trial" data-page="trial">Đăng ký dùng thử</a>`);return bindBuy(plans)}if(page==='invoice')return await invoice();if(page==='security')return await security();if(page==='sessions')return await sessions();if(page==='content')return await contentPage();if(page==='languages')return await languagesPage();if(page==='templates')return await templatesPage();if(page==='backups')return await backupsPage();if(page==='mailboxes')return await mailboxBackupsPage();if(page==='recovery')return await recoveryPage();if(page==='reconciliation')return await reconciliationPage();if(page==='placements')return await placementsPage();if(page==='operations')return await operations();if(page==='reports')return await reportsPage();if(page==='health')return await healthPage();if(page==='trial')return await trial();return await resourcePage(page)}catch(e){shell(`<div class="card"><h2>${tr('Không thể tải trang','Unable to load page')}</h2><p class="error">${escape(e.message)}</p><a class="button" href="/khach-hang" data-page="dashboard">${tr('Về tổng quan','Back to overview')}</a></div>`);}}
window.addEventListener('popstate',render);
(async()=>{try{content=await api('content?lang='+lang);lang=content.language||'vi'}catch{}try{session=await api('auth/me');csrf=session.csrf}catch{}await render()})();

async function reportsPage(){const servers=await api('resources/servers');shell(`<h1>Báo cáo mail theo tháng</h1><div class="card"><form id="report-history"><label>Server<select name="server_id">${servers.items.map(s=>`<option value="${s.id}">${escape(s.name)}</option>`).join('')}</select></label>${field('month','Tháng UTC','month',new Date().toISOString().slice(0,7))}<label>Loại<select name="kind"><option value="reports">Tất cả báo cáo</option>${['dmarc','tls','arf','dsn','metric'].map(k=>`<option>${k}</option>`).join('')}</select></label>${field('domain','Domain (không bắt buộc)','text','',false)}<button type="submit">Xem báo cáo</button></form><button id="report-csv" class="secondary">Xuất CSV</button><button id="report-ndjson" class="secondary">Xuất NDJSON / SIEM</button><div id="report-summary"></div><div id="report-rows" class="table-wrap"></div></div><div class="card"><h2>Nhập báo cáo</h2><p>DMARC XML, TLS JSON, ARF JSON hoặc DSN; hỗ trợ gzip. Tối đa 8 MB sau giải nén.</p><form id="report-import"><label>Loại<select name="kind">${['dmarc','tls','arf','dsn'].map(k=>`<option>${k}</option>`).join('')}</select></label><label>Tệp<input name="file" type="file" required></label><button type="submit">Nhập báo cáo</button></form><p id="report-import-result"></p></div>`);
 const query=()=>new URLSearchParams(Object.fromEntries(new FormData($('#report-history'))));formHandler('#report-history',async()=>{const r=await api('reports?'+query());const sum=r.items.reduce((n,row)=>({total:n.total+Number(row.total),passed:n.passed+Number(row.passed),failed:n.failed+Number(row.failed)}),{total:0,passed:0,failed:0});$('#report-summary').textContent=`${r.items.length} báo cáo · Tổng ${sum.total} · Đạt ${sum.passed} · Lỗi ${sum.failed}`;$('#report-rows').innerHTML=`<table><thead><tr><th>Loại</th><th>Domain</th><th>Thời gian</th><th>Tổng</th><th>Đạt</th><th>Lỗi</th><th>Chi tiết</th></tr></thead><tbody>${r.items.map(row=>`<tr><td>${escape(row.kind)}</td><td>${escape(row.domain_name)}</td><td>${escape(row.period_start)}</td><td>${escape(row.total)}</td><td>${escape(row.passed)}</td><td>${escape(row.failed)}</td><td><details><summary>${escape(row.report_id)}</summary><pre>${escape(JSON.stringify(row.summary,null,2))}</pre></details></td></tr>`).join('')}</tbody></table>`;});for(const format of ['csv','ndjson'])$('#report-'+format).onclick=async()=>{try{await downloadFile('reports?'+query()+'&format='+format,'mail-reports.'+format)}catch(e){toast(e.message)}};
 formHandler('#report-import',async(d,form)=>{const file=form.elements.file.files[0];if(file.size>8*1024*1024)throw Error('Tệp tối đa 8 MB');const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Không đọc được tệp'));reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.readAsDataURL(file)});const r=await api('reports/import',{server_id:Number($('#report-history').elements.server_id.value),kind:d.kind,file:encoded});$('#report-import-result').textContent=`Đã nhập ${r.inserted}; bỏ qua ${r.duplicates} báo cáo trùng`;});}
async function healthPage(){const servers=await api('resources/servers');shell(`<h1>Sức khỏe server & dung lượng</h1><div class="card"><form id="health-select"><label>Server<select name="server_id">${servers.items.map(s=>`<option value="${s.id}">${escape(s.name)}${s.dry_run?' (dry-run)':''}</option>`).join('')}</select></label><button type="submit">Xem lịch sử</button></form><button id="health-check" class="secondary">Kiểm tra ngay</button><div id="health-result"></div><div id="health-history" class="table-wrap"></div><div id="health-accounts" class="table-wrap"></div></div><div class="card"><h2>Cài đặt giám sát</h2><form id="health-config"><label><input name="enabled" type="checkbox"> Tự động kiểm tra</label>${field('monitor_interval','Chu kỳ (giây)','number',300)}${field('failure_threshold','Số lần lỗi liên tiếp để cảnh báo','number',3)}${field('queue_threshold','Ngưỡng hàng đợi','number',1000)}<label><input name="usage_monitor" type="checkbox"> Theo dõi dung lượng hộp thư</label><label><input name="probe_ports" type="checkbox"> Kiểm tra kết nối SMTP/IMAP</label><label><input name="notify_enabled" type="checkbox"> Gửi email cảnh báo</label>${field('recipients','Email nhận cảnh báo (phân cách dấu phẩy)','text','',false)}<button type="submit">Lưu cài đặt</button></form><p class="note">Chỉ số chưa đọc được hiển thị là “Chưa biết”. Dry-run được tách khỏi thống kê server thật.</p></div>`);
 const id=()=>Number($('#health-select').elements.server_id.value);const known=v=>v===null||v===undefined?'Chưa biết':escape(v);async function load(){if(!id()){$('#health-history').textContent=tr('Chưa cấu hình server Stalwart','No Stalwart server configured');$('#health-check').disabled=true;$('#health-config button').disabled=true;return}const r=await api('monitor?server_id='+id());$('#health-history').innerHTML=`<h2>30 ngày gần nhất</h2><table><thead><tr><th>Ngày UTC</th><th>Lần kiểm tra</th><th>API kết nối</th><th>Hàng đợi lớn nhất</th><th>Lỗi đồng bộ lớn nhất</th><th>Tài khoản</th><th>Domain</th></tr></thead><tbody>${r.daily.map(d=>`<tr>${[d.date,d.checks,d.api_pass,d.queue_max,d.sync_max,d.accounts,d.domains].map(v=>`<td>${known(v)}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="7">Chưa có dữ liệu server thật</td></tr>'}</tbody></table>`;$('#health-accounts').innerHTML=`<h2>Dung lượng hộp thư</h2><table><thead><tr><th>Email</th><th>Dung lượng dùng</th><th>Quota MB</th><th>Lần cập nhật</th></tr></thead><tbody>${r.accounts.map(a=>`<tr><td>${escape(a.email)}</td><td>${a.synced_at?escape((a.used_bytes/1048576).toFixed(2))+' MB':'Chưa biết'}</td><td>${known(a.storage_limit_mb)}</td><td>${known(a.synced_at)}</td></tr>`).join('')}</tbody></table>`;const s=servers.items.find(s=>s.id===id()),f=$('#health-config');for(const key of ['monitor_interval','failure_threshold','queue_threshold'])f.elements[key].value=s[key];for(const key of ['usage_monitor','probe_ports','notify_enabled'])f.elements[key].checked=s[key]===1;f.elements.enabled.checked=!!s.next_check_at;f.elements.recipients.value=(s.notify_recipients||[]).join(',');}
 formHandler('#health-select',load);$('#health-check').onclick=async e=>{e.target.disabled=true;try{const r=await api('servers/'+id()+'/check',{});$('#health-result').innerHTML=`<p>${escape(r.mode)} · ${escape(r.status)}</p><pre>${escape(JSON.stringify(r.metrics,null,2))}</pre>`;await load()}catch(err){toast(err.message)}finally{e.target.disabled=false}};formHandler('#health-config',async(d,f)=>{const data={monitor_interval:Number(d.monitor_interval),failure_threshold:Number(d.failure_threshold),queue_threshold:Number(d.queue_threshold),notify_recipients:d.recipients.split(',').map(s=>s.trim()).filter(Boolean)};for(const key of ['enabled','usage_monitor','probe_ports','notify_enabled'])data[key]=f.elements[key].checked;await api('servers/'+id()+'/monitor',data);toast('Đã lưu cài đặt giám sát');});await load();}
async function mailboxBackupsPage(){const r=await api('mailbox-backups');shell(`<h1>Backup & phục hồi hộp thư</h1><p class="alert">Archive mã hóa bằng APP_KEY; giữ khóa ở nơi an toàn. Phục hồi bổ sung vào hộp thư thử nghiệm, cần preview mới trong 15 phút.</p><div class="card"><h2>Hồ sơ hộp thư</h2><form id="mailbox-profile">${field('account_id','ID hộp thư','number')}${field('jmap_url','URL JMAP session HTTPS','url')}${field('app_password','Mật khẩu ứng dụng (để trống để giữ)','password','',false)}${field('config_version','Phiên bản hồ sơ (0 nếu mới)','number',0)}${field('interval_hours','Chu kỳ giờ','number',24)}${field('keep_local','Số bản giữ cục bộ','number',7)}<label><input name="enabled" type="checkbox"> Backup tự động</label><label><input name="restore_target" type="checkbox"> Hộp thư thử nghiệm cho phục hồi</label><button type="submit">Lưu hồ sơ</button></form><div class="table-wrap"><table><thead><tr><th>ID</th><th>Hộp thư</th><th>Phiên bản</th><th>Lịch</th><th>Thử nghiệm</th><th></th></tr></thead><tbody>${r.profiles.map(p=>`<tr><td>${p.id}</td><td>${escape(p.username)}</td><td>${p.config_version}</td><td>${p.enabled?'Bật':'Tắt'}</td><td>${p.restore_target?'Có':'Không'}</td><td><button class="secondary" data-mailbox-edit="${p.id}">Sửa</button></td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Tác vụ backup / phục hồi</h2><form id="mailbox-job"><label>Hồ sơ nguồn<select name="profile_id">${r.profiles.map(p=>`<option value="${p.id}">${escape(p.username)}</option>`).join('')}</select></label><label>Thao tác<select name="kind"><option value="backup">Backup mới</option><option value="upload">Upload lại cloud</option><option value="retrieve">Tải archive từ cloud</option><option value="restore_preview">Xem trước phục hồi</option><option value="restore">Phục hồi bổ sung</option></select></label><label>Archive nguồn<select name="artifact_id"><option value="">Chọn khi cần</option>${r.artifacts.map(a=>`<option value="${a.id}">#${a.id} · hồ sơ ${a.profile_id} · ${escape(a.created_at)}</option>`).join('')}</select></label><label>Hộp thư đích thử nghiệm<select name="target_profile_id"><option value="">Chọn khi phục hồi</option>${r.profiles.filter(p=>p.restore_target).map(p=>`<option value="${p.id}">${escape(p.username)}</option>`).join('')}</select></label><label>Preview đã hoàn tất<select name="preview_id"><option value="">Chọn khi xác nhận phục hồi</option>${r.jobs.filter(j=>j.kind==='restore_preview'&&j.status==='done').map(j=>`<option value="${j.id}">#${j.id} · archive ${j.source_artifact_id} · đích ${j.target_profile_id}</option>`).join('')}</select></label>${field('confirmation','Nhập RESTORE khi phục hồi','text','',false)}<button type="submit">Xếp lịch tác vụ</button></form><p class="note">Worker mailbox riêng chạy Vandelay. Cloud dùng đích rclone đã cấu hình tại Backup panel.</p></div><div class="card"><h2>Archive</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Hồ sơ</th><th>Tạo lúc</th><th>Byte</th><th>Cục bộ</th><th>Cloud</th><th></th></tr></thead><tbody>${r.artifacts.map(a=>`<tr><td>${a.id}</td><td>${a.profile_id}</td><td>${escape(a.created_at)}</td><td>${a.bytes}</td><td>${escape(a.local_status)}</td><td>${escape(JSON.stringify(a.destinations))}</td><td>${a.local_status==='ready'?`<button class="secondary" data-mailbox-download="${a.id}">Tải archive</button>`:''}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Kết quả tác vụ</h2><button id="mailbox-refresh" class="secondary">Làm mới</button><div class="table-wrap" id="mailbox-jobs"><table><thead><tr><th>ID</th><th>Thao tác</th><th>Trạng thái</th><th>Kết quả</th></tr></thead><tbody>${r.jobs.map(j=>`<tr><td>${j.id}</td><td>${escape(j.kind)}</td><td>${badge(j.status)}</td><td><pre>${escape(j.error||JSON.stringify(j.result,null,2))}</pre></td></tr>`).join('')}</tbody></table></div></div>`);
 formHandler('#mailbox-profile',async(d,f)=>{await api('mailbox-backups',{...d,account_id:Number(d.account_id),config_version:Number(d.config_version),interval_hours:Number(d.interval_hours),keep_local:Number(d.keep_local),enabled:f.elements.enabled.checked,restore_target:f.elements.restore_target.checked});toast('Đã lưu hồ sơ');await mailboxBackupsPage()});document.querySelectorAll('[data-mailbox-edit]').forEach(b=>b.onclick=()=>{const p=r.profiles.find(p=>p.id===Number(b.dataset.mailboxEdit)),f=$('#mailbox-profile');for(const key of ['account_id','jmap_url','config_version','interval_hours','keep_local'])f.elements[key].value=p[key];for(const key of ['enabled','restore_target'])f.elements[key].checked=p[key]===1;f.elements.app_password.value='';f.scrollIntoView({behavior:'smooth'});});formHandler('#mailbox-job',async d=>{const data={profile_id:Number(d.profile_id),kind:d.kind,confirmation:d.confirmation};for(const key of ['artifact_id','target_profile_id','preview_id'])if(d[key])data[key]=Number(d[key]);const result=await api('mailbox-backups/jobs',data);toast('Đã xếp lịch tác vụ #'+result.job_id);await mailboxBackupsPage()});document.querySelectorAll('[data-mailbox-download]').forEach(b=>b.onclick=async()=>{try{await downloadFile('mailbox-backups/artifacts/'+b.dataset.mailboxDownload+'/download','mailbox-'+b.dataset.mailboxDownload+'.mbenc')}catch(e){toast(e.message)}});$('#mailbox-refresh').onclick=mailboxBackupsPage;}
async function recoveryPage(){const r=await api('recovery');shell(`<h1>Recovery cấu hình & backend Stalwart</h1><p class="alert">Nguồn snapshot và adapter do người vận hành khai báo trên máy. Preview chưa xác nhận backend được nạp; cần kiểm chứng riêng sau diễn tập.</p>${r.source_keys.length?'':'<p class="error">Chưa khai báo RECOVERY_SOURCES_FILE. Thêm nguồn snapshot nhất quán và đích diễn tập cô lập trong cấu hình máy.</p>'}<div class="card"><h2>Hồ sơ recovery</h2><form id="recovery-profile">${field('server_id','ID server','number')}${field('name','Tên hồ sơ')}<label>Nguồn cấu hình máy<select name="source_key">${r.source_keys.map(k=>`<option>${escape(k)}</option>`).join('')}</select></label>${field('object_types','Object cấu hình cần backup','text','Domain,Account,Role,Tenant,DkimSignature')}${field('version','Phiên bản hồ sơ (0 nếu mới)','number',0)}${field('interval_hours','Chu kỳ giờ','number',24)}${field('keep_local','Số bản giữ cục bộ','number',7)}<label>Vault credential JSON (để trống để giữ)<textarea name="vault_json" autocomplete="off"></textarea></label><label><input type="checkbox" name="enabled"> Backup tự động</label><label><input type="checkbox" name="restore_target"> Server diễn tập cô lập</label><button type="submit">Lưu hồ sơ</button></form><div class="table-wrap"><table><thead><tr><th>ID</th><th>Server</th><th>Tên</th><th>Phiên bản</th><th>Diễn tập</th><th></th></tr></thead><tbody>${r.profiles.map(p=>`<tr><td>${p.id}</td><td>${p.server_id}</td><td>${escape(p.name)}</td><td>${p.version}</td><td>${p.restore_target?'Có':'Không'}</td><td><button class="secondary" data-recovery-edit="${p.id}">Sửa</button></td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Tác vụ recovery</h2><form id="recovery-job"><label>Hồ sơ nguồn<select name="profile_id">${r.profiles.map(p=>`<option value="${p.id}">${escape(p.name)}</option>`).join('')}</select></label><label>Thao tác<select name="kind"><option value="backup">Backup snapshot</option><option value="upload">Upload lại cloud</option><option value="retrieve">Tải snapshot từ cloud</option><option value="restore_preview">Preview diễn tập</option><option value="restore">Phục hồi vào môi trường diễn tập</option></select></label><label>Archive<select name="artifact_id"><option value="">Chọn khi cần</option>${r.artifacts.map(a=>`<option value="${a.id}">#${a.id} · hồ sơ ${a.profile_id} · ${escape(a.created_at)}</option>`).join('')}</select></label><label>Server đích diễn tập<select name="target_profile_id"><option value="">Chọn khi phục hồi</option>${r.profiles.filter(p=>p.restore_target).map(p=>`<option value="${p.id}">${escape(p.name)}</option>`).join('')}</select></label><label>Preview hoàn tất<select name="preview_id"><option value="">Chọn khi xác nhận</option>${r.jobs.filter(j=>j.kind==='restore_preview'&&j.status==='done').map(j=>`<option value="${j.id}">#${j.id} · archive ${j.artifact_id} · đích ${j.target_profile_id}</option>`).join('')}</select></label>${field('confirmation','Nhập RESTORE_SERVER khi phục hồi','text','',false)}<button type="submit">Xếp lịch</button></form><p class="note">Chạy worker recovery riêng. Chỉ server khác origin, không primary, không có tài nguyên panel và đã chặn gửi ra ngoài được dùng làm đích.</p></div><div class="card"><h2>Archive</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Snapshot</th><th>Byte</th><th>Cục bộ</th><th>Cloud</th><th></th></tr></thead><tbody>${r.artifacts.map(a=>`<tr><td>${a.id}</td><td>${escape(a.manifest.snapshot_id)}</td><td>${a.bytes}</td><td>${escape(a.local_status)}</td><td>${escape(JSON.stringify(a.destinations))}</td><td>${a.local_status==='ready'?`<button class="secondary" data-recovery-download="${a.id}">Tải archive</button>`:''}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Diễn tập & kết quả</h2><button class="secondary" id="recovery-refresh">Làm mới</button><div class="table-wrap"><table><thead><tr><th>ID</th><th>Thao tác</th><th>Trạng thái</th><th>Kết quả / RPO / RTO</th><th></th></tr></thead><tbody>${r.jobs.map(j=>`<tr><td>${j.id}</td><td>${escape(j.kind)}</td><td>${badge(j.status)}</td><td><pre>${escape(j.error||JSON.stringify(j.result,null,2))}</pre></td><td>${j.kind==='restore'&&j.status==='done'&&!j.result?.attested_at?`<button data-recovery-attest="${j.id}" class="secondary">Ghi biên bản kiểm chứng</button>`:''}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>DKIM khẩn cấp</h2><p>Chọn khóa active, selector mới và hồ sơ recovery có DkimSignature. Domain phải dùng DKIM Manual khi tạo khóa. Chỉ kích hoạt sau khi xác minh public key mới trên DNS.</p><form id="emergency-create">${field('server_id','ID server','number')}${field('domain_id','ID domain panel','number')}${field('old_key_id','ID khóa active cũ')}${field('selector','Selector mới')}<button type="submit">Tạo kế hoạch & khóa RSA</button></form><div id="emergency-plans"></div></div>`);
 formHandler('#recovery-profile',async(d,f)=>{await api('recovery',{...d,server_id:Number(d.server_id),version:Number(d.version),interval_hours:Number(d.interval_hours),keep_local:Number(d.keep_local),enabled:f.elements.enabled.checked,restore_target:f.elements.restore_target.checked});toast('Đã lưu hồ sơ');await recoveryPage()});document.querySelectorAll('[data-recovery-edit]').forEach(b=>b.onclick=()=>{const p=r.profiles.find(p=>p.id===Number(b.dataset.recoveryEdit)),f=$('#recovery-profile');for(const key of ['server_id','name','source_key','version','interval_hours','keep_local'])f.elements[key].value=p[key];f.elements.object_types.value=p.object_types.join(',');f.elements.vault_json.value='';for(const key of ['enabled','restore_target'])f.elements[key].checked=p[key]===1;f.scrollIntoView({behavior:'smooth'});});formHandler('#recovery-job',async d=>{const data={profile_id:Number(d.profile_id),kind:d.kind,confirmation:d.confirmation};for(const key of ['artifact_id','target_profile_id','preview_id'])if(d[key])data[key]=Number(d[key]);const result=await api('recovery/jobs',data);toast('Đã xếp lịch tác vụ #'+result.job_id);await recoveryPage()});$('#recovery-refresh').onclick=recoveryPage;document.querySelectorAll('[data-recovery-download]').forEach(b=>b.onclick=async()=>{try{await downloadFile('recovery/artifacts/'+b.dataset.recoveryDownload+'/download','recovery-'+b.dataset.recoveryDownload+'.rcenc')}catch(e){toast(e.message)}});
 document.querySelectorAll('[data-recovery-attest]').forEach(b=>b.onclick=()=>{const keys={backend_loaded:'Backend đã nạp',credentials_checked:'Đã kiểm tra credential',mail_folders_checked:'Đã kiểm tra thư/thư mục',attachments_checked:'Đã kiểm tra file đính kèm',queue_checked:'Đã kiểm tra hàng đợi',outbound_isolated:'Đã cô lập gửi thư ra ngoài'};modal('Biên bản diễn tập',Object.entries(keys).map(([key,label])=>`<label><input type="checkbox" name="${key}" required> ${escape(label)}</label>`).join('')+'<label>Bằng chứng và cách kiểm tra<textarea name="note" minlength="20" required></textarea></label>',async(d,f)=>{await api('recovery/jobs/'+b.dataset.recoveryAttest+'/attest',{note:d.note,...Object.fromEntries(Object.keys(keys).map(k=>[k,f.elements[k].checked]))});closeModal();await recoveryPage();});});
 async function keys(){const k=await api('emergency-dkim');$('#emergency-plans').innerHTML=k.items.map(p=>{const phase=p.status==='ready'?'stage':p.status==='staged'?'activate':p.status==='active'?'verify':'';const token={stage:'STAGE_DKIM',activate:'ACTIVATE_DKIM',verify:'VERIFY_DKIM'}[phase];return `<div class="card"><h3>Kế hoạch #${p.id} · ${escape(p.status)}</h3><p>Selector: ${escape(p.selector)}</p><pre>${escape(p.public_value)}</pre>${p.error?`<p class="error">${escape(p.error)}</p>`:''}${phase?`<button class="secondary" data-dkim-id="${p.id}" data-dkim-phase="${phase}" data-dkim-token="${token}">${{stage:'Tạo khóa pending',activate:'Chứng minh DNS & kích hoạt',verify:'Xác minh đã gỡ public key cũ'}[phase]}</button>`:''}</div>`;}).join('');document.querySelectorAll('[data-dkim-id]').forEach(b=>b.onclick=()=>modal('Xác nhận DKIM',field('confirmation','Nhập '+b.dataset.dkimToken),async d=>{const result=await api('emergency-dkim/'+b.dataset.dkimId+'/apply',{phase:b.dataset.dkimPhase,confirmation:d.confirmation});closeModal();toast(result.status);await keys();},'Thực hiện'));}
 formHandler('#emergency-create',async d=>{await api('emergency-dkim',{...d,server_id:Number(d.server_id),domain_id:Number(d.domain_id)});toast('Đã tạo kế hoạch DKIM');await keys()});await keys();}

async function placementsPage(){const r=await api('placements');shell(`<h1>${title('placements')}</h1><p>${tr('Phân bổ khách hàng chỉ áp dụng cho domain tạo mới. Chuyển domain hiện hữu bằng kế hoạch migration đã kiểm chứng.','Customer placement applies to new domains. Move existing domains using a verified migration plan.')}</p><div class="card"><h2>${tr('Server mặc định của khách hàng','Customer default server')}</h2><form id="placement-form">${field('customer_id',tr('ID khách hàng','Customer ID'),'number')}<label>${tr('Server','Server')}<select name="server_id">${r.capacities.filter(c=>c.active===1).map(c=>`<option value="${c.server_id}">${escape(c.name)}</option>`).join('')}</select></label>${field('version',tr('Phiên bản (0 nếu mới)','Version (0 for new)'),'number',0)}<button>${tr('Lưu','Save')}</button></form><pre>${escape(JSON.stringify(r.placements,null,2))}</pre></div><div class="card"><h2>${tr('Hạn mức & chi phí','Limits & costs')}</h2><form id="capacity-form"><label>Server<select name="server_id">${r.capacities.filter(c=>c.active===1).map(c=>`<option value="${c.server_id}">${escape(c.name)}</option>`).join('')}</select></label>${field('max_accounts',tr('Tối đa hộp thư (0: không giới hạn)','Maximum accounts (0: unlimited)'),'number',0)}${field('storage_budget_gb',tr('Dung lượng dự kiến GB','Storage budget GB'),'number',0)}${field('cost_per_gb',tr('Chi phí mỗi GB','Cost per GB'),'number',0)}${field('fixed_cost',tr('Chi phí cố định','Fixed cost'),'number',0)}<button>${tr('Lưu','Save')}</button></form><p>${tr('Dung lượng chỉ tính từ quan sát trong 24 giờ; stale_accounts là số hộp thư chưa có số liệu mới. Dung lượng dự kiến phục vụ lập kế hoạch, không tự giới hạn storage.','Storage totals use observations from the last 24 hours; stale_accounts counts accounts without fresh data. Storage budgets support planning and do not enforce storage limits.')}</p><pre>${escape(JSON.stringify(r.capacities,null,2))}</pre></div>`);formHandler('#placement-form',async d=>{await api('placements',{kind:'customer',customer_id:Number(d.customer_id),server_id:Number(d.server_id),version:Number(d.version)});await placementsPage()});const f=$('#capacity-form');const populate=()=>{const c=r.capacities.find(c=>c.server_id===Number(f.elements.server_id.value));if(c)for(const k of ['max_accounts','storage_budget_gb','cost_per_gb','fixed_cost'])f.elements[k].value=c[k]};f.elements.server_id.onchange=populate;populate();formHandler('#capacity-form',async d=>{await api('placements',{...d,kind:'capacity',server_id:Number(d.server_id),max_accounts:Number(d.max_accounts)});await placementsPage()});}

async function reconciliationPage(){const servers=await api('resources/servers');let run=null,cursor=0,next=null;shell(`<h1>${title('reconciliation')}</h1><p>${tr('So sánh domain, quota và alias với tài nguyên đã liên kết. Tài nguyên chỉ có ở remote cần xử lý thủ công.','Compare domains, quotas and aliases for linked resources. Remote-only objects require manual review.')}</p><form id="reconcile-preview"><label>Server<select name="server_id">${servers.items.map(s=>`<option value="${s.id}">${escape(s.name)}</option>`).join('')}</select></label><button ${servers.items.length?'':'disabled'}>${tr('Xem trước','Preview')}</button></form><div id="reconcile-summary"></div><div class="table-wrap" id="reconcile-items"></div><button id="reconcile-apply" hidden>${tr('Áp dụng mục đã chọn','Apply selected changes')}</button><button id="reconcile-next" hidden class="secondary">${tr('Trang tiếp','Next page')}</button>`);async function load(){const r=await api('reconciliation/'+run+'?offset='+cursor);next=r.next;$('#reconcile-summary').innerHTML=`<p>${escape(r.run.mode)} · ${r.total} ${tr('mục','items')}</p><pre>${escape(JSON.stringify(r.run.summary,null,2))}</pre>`;$('#reconcile-items').innerHTML=`<table><thead><tr><th>${tr('Chọn','Select')}</th><th>${tr('Tài nguyên','Resource')}</th><th>${tr('Trạng thái','Status')}</th><th>${tr('Trước / mong muốn','Before / desired')}</th></tr></thead><tbody>${r.items.map(i=>`<tr><td>${i.status==='diff'&&r.run.mode==='live'?`<input type="checkbox" data-reconcile-id="${i.id}" aria-label="${escape(i.label)}">`:''}</td><td>${escape(i.label)}</td><td>${badge(i.status)} ${escape(i.detail||'')}</td><td><details><summary>${tr('Chi tiết','Details')}</summary><pre>${escape(JSON.stringify({before:i.before_data,desired:i.desired_data},null,2))}</pre></details></td></tr>`).join('')}</tbody></table>`;$('#reconcile-apply').hidden=r.run.mode!=='live'||!r.items.some(i=>i.status==='diff');$('#reconcile-next').hidden=next===null;}formHandler('#reconcile-preview',async d=>{const r=await api('reconciliation',{server_id:Number(d.server_id)});run=r.run_id;cursor=0;await load()});$('#reconcile-next').onclick=async()=>{cursor=next;try{await load()}catch(e){toast(e.message)}};$('#reconcile-apply').onclick=()=>{const ids=[...document.querySelectorAll('[data-reconcile-id]:checked')].map(e=>Number(e.dataset.reconcileId));if(!ids.length||ids.length>50)return toast(tr('Chọn từ 1 đến 50 mục','Select 1 to 50 changes'));modal(tr('Xác nhận đối chiếu','Confirm reconciliation'),field('confirmation',tr('Nhập RECONCILE','Type RECONCILE')),async d=>{const result=await api('reconciliation/'+run+'/apply',{...d,item_ids:ids});closeModal();toast(JSON.stringify(result));await load()});};}
